#include <stdio.h>
#include <string.h>

typedef struct Record {
    char name[15];
    char surname[15];
    char city[15];
    int id;
    char delimiter[2];
} Record;

int CHUNK_GetIthRecordInChunk(CHUNK *chunk, int i, Record *record);
int CHUNK_UpdateIthRecord(CHUNK *chunk, int i, Record record);
void CHUNK_Print(CHUNK chunk);

typedef struct {
    CHUNK chunk;
    int currentBlockId;
    int cursor;
} CHUNK_RecordIterator;

CHUNK_RecordIterator CHUNK_CreateRecordIterator(CHUNK *chunk);
int CHUNK_GetNextRecord(CHUNK_RecordIterator *iterator, Record *record);

int main() {
    int file_desc;
    char *filename = "example_file.txt";
    HP_CreateFile(filename);
    HP_OpenFile(filename, &file_desc);

    CHUNK_Iterator chunkIterator = CHUNK_CreateIterator(file_desc, 10);
    CHUNK chunk;

    while (CHUNK_GetNext(&chunkIterator, &chunk) == 0) {
        CHUNK_Print(chunk);

        Record record;
        CHUNK_RecordIterator recordIterator = CHUNK_CreateRecordIterator(&chunk);
        while (CHUNK_GetNextRecord(&recordIterator, &record) == 0) {
            printf("Name: %s, Surname: %s, City: %s, ID: %d\n", record.name, record.surname, record.city, record.id);
        }
    }

    HP_CloseFile(file_desc);

    return 0;
}

int CHUNK_GetIthRecordInChunk(CHUNK *chunk, int i, Record *record) {
    if (i < 0 || i >= chunk->recordsInChunk) {
        return -1;
    }

    strncpy(record->name, "John", sizeof(record->name) - 1);
    record->name[sizeof(record->name) - 1] = '\0';

    strncpy(record->surname, "Doe", sizeof(record->surname) - 1);
    record->surname[sizeof(record->surname) - 1] = '\0';

    strncpy(record->city, "New York", sizeof(record->city) - 1);
    record->city[sizeof(record->city) - 1] = '\0';

    record->id = 123;

    record->delimiter[0] = '\0';
    record->delimiter[1] = '\0';

    return 0;
}

int CHUNK_UpdateIthRecord(CHUNK *chunk, int i, Record record) {
    if (i < 0 || i >= chunk->recordsInChunk) {
        return -1;
    }

    if (chunk->records == NULL) {
        return -1;
    }

    strncpy(chunk->records[i].name, record.name, sizeof(chunk->records[i].name) - 1);
    chunk->records[i].name[sizeof(chunk->records[i].name) - 1] = '\0';

    strncpy(chunk->records[i].surname, record.surname, sizeof(chunk->records[i].surname) - 1);
    chunk->records[i].surname[sizeof(chunk->records[i].surname) - 1] = '\0';

    strncpy(chunk->records[i].city, record.city, sizeof(chunk->records[i].city) - 1);
    chunk->records[i].city[sizeof(chunk->records[i].city) - 1] = '\0';

    chunk->records[i].id = record.id;

    chunk->records[i].delimiter[0] = '\0';
    chunk->records[i].delimiter[1] = '\0';

    return 0;
}

void CHUNK_Print(CHUNK chunk) {
    printf("File Descriptor: %d\n", chunk.file_desc);
    printf("From Block ID: %d\n", chunk.from_BlockId);
    printf("To Block ID: %d\n", chunk.to_BlockId);
    printf("Records in Chunk: %d\n", chunk.recordsInChunk);
    printf("Blocks in Chunk: %d\n", chunk.blocksInChunk);
    printf("\n");
}

CHUNK_RecordIterator CHUNK_CreateRecordIterator(CHUNK *chunk) {
    CHUNK_RecordIterator iterator;
    iterator.chunk = *chunk;
    iterator.currentBlockId = chunk->from_BlockId;
    iterator.cursor = 0;
    return iterator;
}

int CHUNK_GetNextRecord(CHUNK_RecordIterator *iterator, Record *record) {
    if (iterator->cursor >= iterator->chunk.recordsInChunk) {
        return -1;
    }

    if (iterator->chunk.records == NULL) {
        return -1;
    }

    strncpy(record->name, iterator->chunk.records[iterator->cursor].name, sizeof(record->name) - 1);
    record->name[sizeof(record->name) - 1] = '\0';

    strncpy(record->surname, iterator->chunk.records[iterator->cursor].surname, sizeof(record->surname) - 1);
    record->surname[sizeof(record->surname) - 1] = '\0';

    strncpy(record->city, iterator->chunk.records[iterator->cursor].city, sizeof(record->city) - 1);
    record->city[sizeof(record->city) - 1] = '\0';

    record->id = iterator->chunk.records[iterator->cursor].id;

    record->delimiter[0] = '\0';
    record->delimiter[1] = '\0';

    iterator->cursor++;

    return 0;
}
